# CashDeskLast/CashDataModule.dfm:13 ODSCashReport (TOracleDataSet)
SQL_CD_ODSCASHREPORT = "SELECT DISTINCT\n  SUM(PR.LAMMOUNT)  /*/1000 */ AS LAMMOUNTS\n ,PR.KASSA_B     AS BSYMBOL\n ,MAX(CASH.NAME) AS NAME\n ,MIN(CASH.MEDIOCRITY) AS MEDIOCRITY\n FROM PROVARCH PR,KASSA_B CASH\n WHERE\n     DAT>=:FIRSTDATE\n AND DAT<=:LASTDATE\n AND CASH.SYMBOL=PR.KASSA_B\n\n  AND((debt in (Select ac.Id from account ac,Bal_spr1 b where b.cashincoming=1 and b.Bal_cn=ac.Bal_cn1))\n OR\n (Kredit in (Select ac.Id from account ac,Bal_spr1 b where b.cashincoming=1 and b.Bal_cn=ac.Bal_cn1)))\n\n  GROUP BY PR.KASSA_B\n\nUNION\n\nSelect \n  ABS(Sum(Ar.pok_ostat))  /*/1000*/ as LAMMOUNTS\n ,'35' as BSYMBOL\n ,'Hesabat tarixinin əvvəlinə kassanın qalığı' as NAME\n ,0 as MEDIOCRITY\nfrom \n  ACCOUNT AC\n ,ARCHOST AR\n\nwhere\n  AC.ID = AR.ACC_ID \n   and AC.BAL_CN1 in (Select bal_cn from Bal_spr1 where cashincoming=1)\n   and AR.datdate = (Select max(dat) from operkurs where dat<:FirstDate)\n   and ac.val_acc=0\n\nUNION\n\nSelect \n  ABS(Sum(Ar.pok_ostat)) /*/1000 */ as LAMMOUNTS\n ,'70' as BSYMBOL\n ,'Hesabat tarixinin sonuna kassanın qalığı' as NAME\n ,1 as MEDIOCRITY\nfrom \n  ACCOUNT AC\n ,ARCHOST AR\n\nwhere\n  AC.ID = AR.ACC_ID \n   and AC.BAL_CN1 in (Select bal_cn from Bal_spr1 where cashincoming=1)\n   and AR.datdate = (Select max(dat) from operkurs where dat<=:LastDate)\n   and ac.val_acc=0\n\n\nORDER BY\n MEDIOCRITY\n,BSYMBOL\n\n \n \n \n \n \n \n \n \n \n \n \n \n \n \n "

# CashDeskLast/CashDataModule.dfm:137 ODSIOCome (TOracleDataSet)
SQL_CD_ODSIOCOME = 'SELECT\n  PR.LAMMOUNT,PR.AMMOUNT\n ,PR.KASSA_B AS BSYMBOL\n ,AC.ACC_NO AS ACCOUNTNUMBER, PR.NO_PROV\n FROM  ACCOUNT AC,  :prov PR\n WHERE PR.DAT >= :FIRSTDATE AND PR.DAT<=:LASTDATE\n     AND PR.DEBT = AC.ID\n     AND (PR.KREDIT IN (SELECT AC.ID FROM ACCOUNT AC,BAL_SPR1 B WHERE B.BAL_CN=AC.BAL_CN1 AND B.CASHINCOMING=1))\n\nORDER BY\n   pr.no_prov, Pr.kassa_b\n  ,Ac.acc_no\n     \n \n \n \n \n \n '

# CashDeskLast/CashDataModule.dfm:199 ODSTransactionsViewer (TOracleDataSet)
SQL_CD_ODSTRANSACTIONSVIEWER = '/*SELECT DISTINCT\n  PR.DAT,PR.ID as ID\n ,AC1.ACC_NO AS DEBIT,AC1.KLI_ID AS DEBTID,AC1.FILIAL as DebetFilial\n ,AC1.NAME AS DNAME,AC2.KLI_ID AS KREDITID\n ,PR.VAL_ACC AS DCURRENCY, sb_complex_transactions.GetCurrencyName(PR.VAL_ACC) as DebtCurName\n ,AC2.ACC_NO AS KREDIT,AC1.KLI_ID,AC2.FILIAL as CreditFilial\n ,AC2.NAME  AS  KNAME\n ,AC1.BAL_CN1 AS DEBTCOME\n ,AC2.BAL_CN1 AS CREDITCOME\n ,PR.CURRENCYID_C AS KCURRENCY, sb_complex_transactions.GetCurrencyName(PR.CURRENCYID_C) as CreditCurName\n ,PR.AMMOUNT  AS DAMMOUNT\n ,PR.AMMOUNT_C AS KAMMOUNT\n ,PR.LAMMOUNT AS LAMMOUNT\n ,PR.KASSA_B AS BSYMBOL, PR.NO_PROV\n ,PR.OP_ID AS OperatorID , PR.COMMIT_OPID AS CommitterID\n ,PR.NAME AS ASSIGNMENT,c.issuedby,c.seria,c.docnumber,c.person_doc,c.fromwhen\n  FROM  PROVARCH PR,ACCOUNT AC1,ACCOUNT AC2\n      ,BAL_SPR1 REFERENCE\n WHERE\n        AC1.ID=PR.DEBT and pr.id=c.id(+)\n    AND AC2.ID=PR.KREDIT\n    AND PR.DAT>=:FIRSTDATE\n    AND PR.DAT<=:LASTDATE\n\n    AND REFERENCE.CASHINCOMING=1\n    and ac1.bal_cn1<>ac2.bal_cn1 --S.M.21.09.2013\n  \n\n\n\n*/\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nORDER BY  pr.id\n\n \n \n \n \n \n \n '

