# CashDeskLast/CashDataModule.dfm:697 TotalResult (TOracleDataSet)
SQL_CD_TOTALRESULT = 'SELECT\n   DLAMMOUNT\n  ,DAMMOUNT\n  ,DCOUNT\n  ,CLAMMOUNT\n  ,CAMMOUNT\n  ,CCOUNT\n  ,CASHREMAINDER\nFROM\n\n(\n SELECT\n   SUM(PR.LAMMOUNT) as DLAMMOUNT\n  ,SUM(PR.AMMOUNT) as  DAMMOUNT\n  ,COUNT(*) as DCOUNT\n FROM  ACCOUNT AC,PROVARCH PR\n WHERE PR.DAT >=:FirstDate AND PR.DAT<=:LastDate\n     AND PR.KREDIT = AC.ID\n     AND (PR.DEBT IN (SELECT AC.ID FROM ACCOUNT AC,BAL_SPR1 B WHERE B.BAL_CN=AC.BAL_CN1 AND B.CASHINCOMING=1))\n     AND ((PR.val_acc =:CurrencyID) ) AND AC.FILIAL=:BRANCHID\n     AND\n     --NOT PR.KASSA_B IS NULL\n     (Decode(PR.VID_OP,null,1,1,0,1)=1)\n     )\n,\n(\n SELECT\n   SUM(PR.LAMMOUNT) as CLAMMOUNT\n  ,SUM(PR.AMMOUNT_C) as CAMMOUNT\n  ,COUNT(*) as CCOUNT\n FROM  ACCOUNT AC,PROVARCH PR\n WHERE PR.DAT >=:FirstDate AND PR.DAT<=:LastDate\n     AND PR.DEBT = AC.ID\n     AND (PR.KREDIT IN (SELECT AC.ID FROM ACCOUNT AC,BAL_SPR1 B WHERE B.BAL_CN=AC.BAL_CN1 AND B.CASHINCOMING=1))\n     AND ((PR.CURRENCYID_C =:CurrencyID)) AND AC.FILIAL=:BRANCHID\n     AND\n     --NOT PR.KASSA_B IS NULL\n     (Decode(PR.VID_OP,null,1,1,0,1)=1)\n     )\n,\n(\nSelect\n  ABS(Sum(Ar.ostat)) as CASHREMAINDER\nfrom\n  ACCOUNT AC\n ,ARCHOST AR\nwhere\n  AC.ID = AR.ACC_ID\n   and AC.BAL_CN1 in (Select bal_cn from Bal_spr1 where cashincoming=1)\n   and AR.datdate = (Select max(dat) from operkurs where dat<=:LastDate)\n   and ac.val_acc=:CurrencyID and ac.filial=:BRANCHID\n)\n\n\n\n\n\n\n\n\n\n\n\n\n \n \n \n '

