# CashDeskLast/CashDataModule.dfm:1004 OrDS_CashBook (TOracleDataSet)
SQL_CD_ORDS_CASHBOOK = "SELECT DISTINCT\n  SUM(PR.LAMMOUNT)  /*/1000 */ AS LAMMOUNTS\n ,PR.KASSA_B     AS BSYMBOL\n ,MAX(CASH.NAME) AS NAME\n ,MIN(CASH.MEDIOCRITY) AS MEDIOCRITY\n FROM PROVARCH PR,KASSA_B CASH\n WHERE\n     DAT>=:FIRSTDATE\n AND DAT<=:LASTDATE\n AND CASH.SYMBOL=PR.KASSA_B\n\n  AND((debt in (Select ac.Id from account ac,Bal_spr1 b where b.cashincoming=1 and b.Bal_cn=ac.Bal_cn1))\n OR\n (Kredit in (Select ac.Id from account ac,Bal_spr1 b where b.cashincoming=1 and b.Bal_cn=ac.Bal_cn1)))\n\n  GROUP BY PR.KASSA_B\n\nUNION\n\nSelect \n  ABS(Sum(Ar.pok_ostat))  /*/1000*/ as LAMMOUNTS\n ,35 as BSYMBOL\n ,'Hesabat tarixinin əvvəlinə kassanın qalığı' as NAME\n ,0 as MEDIOCRITY\nfrom \n  ACCOUNT AC\n ,ARCHOST AR\n\nwhere\n  AC.ID = AR.ACC_ID \n   and AC.BAL_CN1 in (Select bal_cn from Bal_spr1 where cashincoming=1)\n   and AR.datdate = (Select max(dat) from operkurs where dat<:FirstDate)\n   and ac.val_acc=0\n\nUNION\n\nSelect \n  ABS(Sum(Ar.pok_ostat)) /*/1000 */ as LAMMOUNTS\n ,70 as BSYMBOL\n ,'Hesabat tarixinin sonuna kassanın qalığı' as NAME\n ,1 as MEDIOCRITY\nfrom \n  ACCOUNT AC\n ,ARCHOST AR\n\nwhere\n  AC.ID = AR.ACC_ID \n   and AC.BAL_CN1 in (Select bal_cn from Bal_spr1 where cashincoming=1)\n   and AR.datdate = (Select max(dat) from operkurs where dat<=:LastDate)\n   and ac.val_acc=0\n\n\nORDER BY\n MEDIOCRITY\n,BSYMBOL"

# CashDeskLast/CashDataModule.dfm:1095 ODS_L_CHIN (TOracleDataSet)
SQL_CD_ODS_L_CHIN = 'select rownum, s.* from (SELECT DISTINCT\n  PR.ID as ID\n ,case when AC1.BAL_CN1=:cn then decode(AC1.BAL_CN1,:cn,AC2.ACC_NO,:cn2,AC2.ACC_NO,AC1.ACC_NO) else decode(AC1.BAL_CN1,:cn,AC2.ACC_NO,:cn2,AC2.ACC_NO,AC1.ACC_NO)end as hesab\n ,AC1.ACC_NO AS DEBIT,AC1.KLI_ID AS DEBTID,AC1.FILIAL as DebetFilial,AC1.NAME AS DNAME,AC2.KLI_ID AS KREDITID\n ,case when AC1.BAL_CN1=:cn then decode(AC1.BAL_CN1,:cn,AC2.NAME,:cn2,AC2.NAME,AC1.NAME) else decode(AC1.BAL_CN1,:cn,AC2.NAME,:cn2,AC2.NAME,AC1.NAME)end as hesab_adi\n ,PR.VAL_ACC AS DCURRENCY, sb_complex_transactions.GetCurrencyName(PR.VAL_ACC) as DebtCurName,AC2.ACC_NO AS KREDIT,AC1.KLI_ID,AC2.FILIAL as CreditFilial\n ,AC2.NAME  AS  KNAME ,AC1.BAL_CN1 AS DEBTCOME ,AC2.BAL_CN1 AS CREDITCOME\n ,case when AC1.BAL_CN1=:cn then decode(AC1.BAL_CN1,:cn,0,:cn2,0,:amount) else decode(AC1.BAL_CN1,:cn,0,:cn2,0,:amount) end as mexaric\n ,case when AC2.BAL_CN1=:cn then decode(AC2.BAL_CN1,:cn,0,:cn2,0,:amount) else decode(AC2.BAL_CN1,:cn,0,:cn2,0,:amount) end as medaxil\n  ,PR.CURRENCYID_C AS KCURRENCY, sb_complex_transactions.GetCurrencyName(PR.CURRENCYID_C) as CreditCurName\n  ,PR.AMMOUNT  AS DAMMOUNT ,PR.AMMOUNT_C AS KAMMOUNT ,PR.LAMMOUNT AS LAMMOUNT\n  ,PR.KASSA_B AS BSYMBOL, PR.NO_PROV ,PR.OP_ID AS OperatorID, PR.Commit_OpID as CommitterID\n\n\n\n ,PR.NAME AS ASSIGNMENT\n FROM  PROVARCH PR,ACCOUNT AC1,ACCOUNT AC2\n      ,BAL_SPR1 REFERENCE\n WHERE\n        AC2.ID=PR.KREDIT\n    AND AC1.ID=PR.DEBT\n    AND PR.DAT>=:FIRSTDATE and ((decode(AC2.BAL_CN1,:cn,null,:cn2,null,:amount) is not null) or (decode(AC1.BAL_CN1,:cn,null,:cn2,null,:amount) is not null))\n    AND PR.DAT<=:LASTDATE\n\n    AND REFERENCE.CASHINCOMING=1\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    ORDER BY mexaric,medaxil) s\n\n\n'

# CashDeskLast/CashDataModule.dfm:1329 ODS_EVV_SON_QALIQ (TOracleDataSet)
SQL_CD_ODS_EVV_SON_QALIQ = 'select sel1.Evvele_qaliq,Sel2.Sona_qaliq From\n(select sum(-AR.OSTAT) Evvele_qaliq\nfrom archost AR, Account AC\nwhere AC.id=AR.acc_id\n  and AC.BAL_CN1 in (:c,:c2)\n\n\n  and datdate=\n              :FIRSTDATE-1)/*(select max(AR_S.datdate) from archost AR_S where AR_S.datdate<:FIRSTDATE))*/ sel1,\n\n(select sum(-AR.OSTAT) Sona_qaliq\nfrom archost AR, Account AC\nwhere AC.id=AR.acc_id\n  and AC.BAL_CN1 in (:c,:c2)\n\n\n  and datdate=\n              :LASTDATE/*(select max(AR_S.datdate) from archost AR_S where AR_S.datdate<=:LASTDATE)*/) sel2\n'

