# CashDeskLast/CashDataModule.dfm:1440 newods_lchin (TOracleDataSet)
SQL_CD_NEWODS_LCHIN = "select rownum, s.* from (SELECT DISTINCT\n  PR.ID as ID\n ,case when AC1.BAL_CN1='10010' then decode(AC1.BAL_CN1,'10010',AC2.ACC_NO,'10020',AC2.ACC_NO,AC1.ACC_NO) else decode(AC1.BAL_CN1,'1001',AC2.ACC_NO,'1011',AC2.ACC_NO,AC1.ACC_NO)end as hesab\n ,AC1.ACC_NO AS DEBIT,AC1.KLI_ID AS DEBTID,AC1.FILIAL as DebetFilial,AC1.NAME AS DNAME,AC2.KLI_ID AS KREDITID\n ,case when AC1.BAL_CN1='10010' then decode(AC1.BAL_CN1,'10010',AC2.NAME,'10020',AC2.NAME,AC1.NAME) else decode(AC1.BAL_CN1,'1001',AC2.NAME,'1011',AC2.NAME,AC1.NAME)end as hesab_adi\n ,PR.VAL_ACC AS DCURRENCY, sb_complex_transactions.GetCurrencyName(PR.VAL_ACC) as DebtCurName,AC2.ACC_NO AS KREDIT,AC1.KLI_ID,AC2.FILIAL as CreditFilial\n ,AC2.NAME  AS  KNAME ,AC1.BAL_CN1 AS DEBTCOME ,AC2.BAL_CN1 AS CREDITCOME\n ,case when AC1.BAL_CN1='10010' then decode(AC1.BAL_CN1,'10010',0,'10020',0,PR.AMMOUNT) else decode(AC1.BAL_CN1,'1001',0,'1011',0,PR.AMMOUNT) end as mexaric\n ,case when AC2.BAL_CN1='10010' then decode(AC2.BAL_CN1,'10010',0,'10020',0,PR.AMMOUNT_C) else decode(AC2.BAL_CN1,'1001',0,'1011',0,PR.AMMOUNT_C) end as medaxil\n  ,PR.CURRENCYID_C AS KCURRENCY, sb_complex_transactions.GetCurrencyName(PR.CURRENCYID_C) as CreditCurName\n  ,PR.AMMOUNT  AS DAMMOUNT ,PR.AMMOUNT_C AS KAMMOUNT ,PR.LAMMOUNT AS LAMMOUNT\n  ,PR.KASSA_B AS BSYMBOL, PR.NO_PROV ,PR.OP_ID AS OperatorID, PR.Commit_OpID as CommitterID\n\n\n\n ,PR.NAME AS ASSIGNMENT\n FROM  PROVARCH PR,ACCOUNT AC1,ACCOUNT AC2\n      ,BAL_SPR1 REFERENCE\n WHERE\n        AC2.ID=PR.KREDIT\n    AND AC1.ID=PR.DEBT\n    AND PR.DAT>=:FIRSTDATE and ((decode(AC2.BAL_CN1,'10010',null,'10020',null,PR.AMMOUNT_C) is not null) or (decode(AC1.BAL_CN1,'1001',null,'1011',null,PR.AMMOUNT) is not null))\n    AND PR.DAT<=:LASTDATE\n\n    AND REFERENCE.CASHINCOMING=1\n\n    ORDER BY mexaric,medaxil) s\n\nselect rownum, s.* from (SELECT DISTINCT\n  PR.ID as ID\n ,case when AC1.BAL_CN1=cn then decode(AC1.BAL_CN1,cn,AC2.ACC_NO,cn2,AC2.ACC_NO,AC1.ACC_NO) else decode(AC1.BAL_CN1,cn,AC2.ACC_NO,cn2,AC2.ACC_NO,AC1.ACC_NO)end as hesab\n ,AC1.ACC_NO AS DEBIT,AC1.KLI_ID AS DEBTID,AC1.FILIAL as DebetFilial,AC1.NAME AS DNAME,AC2.KLI_ID AS KREDITID\n ,case when AC1.BAL_CN1=cn then decode(AC1.BAL_CN1,cn,AC2.NAME,cn2,AC2.NAME,AC1.NAME) else decode(AC1.BAL_CN1,cn,AC2.NAME,cn2,AC2.NAME,AC1.NAME)end as hesab_adi\n ,PR.VAL_ACC AS DCURRENCY, sb_complex_transactions.GetCurrencyName(PR.VAL_ACC) as DebtCurName,AC2.ACC_NO AS KREDIT,AC1.KLI_ID,AC2.FILIAL as CreditFilial\n ,AC2.NAME  AS  KNAME ,AC1.BAL_CN1 AS DEBTCOME ,AC2.BAL_CN1 AS CREDITCOME\n ,case when AC1.BAL_CN1=cn then decode(AC1.BAL_CN1,cn,0,cn2,0,PR.AMMOUNT) else decode(AC1.BAL_CN1,cn,0,cn2,0,PR.AMMOUNT) end as mexaric\n ,case when AC2.BAL_CN1=cn then decode(AC2.BAL_CN1,cn,0,cn2,0,PR.AMMOUNT_C) else decode(AC2.BAL_CN1,cn,0,cn2,0,PR.AMMOUNT_C) end as medaxil\n  ,PR.CURRENCYID_C AS KCURRENCY, sb_complex_transactions.GetCurrencyName(PR.CURRENCYID_C) as CreditCurName\n  ,PR.AMMOUNT  AS DAMMOUNT ,PR.AMMOUNT_C AS KAMMOUNT ,PR.LAMMOUNT AS LAMMOUNT\n  ,PR.KASSA_B AS BSYMBOL, PR.NO_PROV ,PR.OP_ID AS OperatorID, PR.Commit_OpID as CommitterID\n\n\n\n ,PR.NAME AS ASSIGNMENT\n FROM  PROVARCH PR,ACCOUNT AC1,ACCOUNT AC2\n      ,BAL_SPR1 REFERENCE\n WHERE\n        AC2.ID=PR.KREDIT\n    AND AC1.ID=PR.DEBT\n    AND PR.DAT>=:FIRSTDATE and ((decode(AC2.BAL_CN1,'10010',null,'10020',null,PR.AMMOUNT_C) is not null) or (decode(AC1.BAL_CN1,'1001',null,'1011',null,PR.AMMOUNT) is not null))\n    AND PR.DAT<=:LASTDATE\n\n    AND REFERENCE.CASHINCOMING=1\n\n    ORDER BY mexaric,medaxil) s"

